const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    await page.goto('http://localhost/index.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(3000);
    console.log('INDEX_OPTIONS: ' + JSON.stringify(await page.$eval('#chooseIndex', el => Array.from(el.options).map(o=>({v:o.value,t:o.textContent.trim()})))));
    await page.selectOption('#chooseIndex', { label: 'index_data_explorer_demo' });
    await page.waitForTimeout(4000);
    await page.click('.oneCollapsibleItem.filter .collapsible-header');
    await page.waitForTimeout(500);
    const fields = await page.$eval('#dataExplorerDataFields', el => Array.from(el.options).map(o=>({v:o.value,t:o.textContent.trim()})));
    console.log('DEMO_FIELDS: ' + JSON.stringify(fields));
    await browser.close();
})().catch(e => { console.error('VERIFY_FAILED', e.message); process.exit(1); });
EOF
